 tabs=sorted(set(p for r in src for p in r['result_table_path'].split(';') if p));scripts=sorted(set(r['script_path'] for r in src))
 slides.append(dict(number=len(slides)+1,title=title,tag=tag,why=why,findings=findings or [],changed=changed,ids=ids,figures=figs,table=table,layout=layout or ('figure' if figs else ('table' if table else 'text')),note=note,foot=foot,sign=sign,result_tables=tabs,scripts=scripts))
